def test_add_double_dash_still_accepted(self):
    code, out, _ = run(["add", self.path, "2024-03-01", "food", "-5", "--", "-refund"])
    self.assertEqual((code, out), (0, "2024-03-01 food -5.00 -refund\n"))

def test_add_malformed_dash_amount_is_invalid_entry(self):
    before = self.read_bytes()
    for amount in ("-1e3", "-abc", "-1.234"):
        code, out, err = run(["add", self.path, "2024-03-07", "groceries", amount])
        self.assertEqual((code, out), (1, ""), amount)
        self.assertTrue(err.startswith("pennywise: invalid entry: "), err)
        self.assertEqual(self.read_bytes(), before, amount)

def test_add_dash_leading_category(self):
    code, out, _ = run(["add", self.path, "2024-03-01", "-food", "-5"])
    self.assertEqual((code, out), (0, "2024-03-01 -food -5.00\n"))

