    before = self.read_bytes()
    for rest in ([], ["2024-03-01", "x"], ["2024-03-01", "x", "1", "n", "extra"]):
        code, out, err = run(["add", self.path] + rest)
        self.assertEqual((code, out), (2, ""), rest)
        self.assertIn("expected FILE DATE CATEGORY AMOUNT", err)
        self.assertEqual(self.read_bytes(), before)

